  "player_descriptions": {
    "14": "Naima, your goal was crucial to our narrow victory! You showed great attacking intent, and your dribbling caused problems for the opposition. Keep up the good work!",
    "15": "Tanay, you put in a solid shift in defensive midfield. Your interceptions and tackles were vital in protecting our defense, even if your shot didn't quite hit the mark. Your defensive work rate was key to securing the win.",
    "2": "Kavin, your playmaking ability shone through in this match, not to mention that assist! Your passing and vision created several opportunities for the team, helping secure that narrow win. Keep those passes coming, mate!",
    "5": "Rohan, your energy in midfield was fantastic and those saves definitely helped us get over the line! You were always looking to win the ball back, and those interceptions were game-changers. Your work rate is an example to everyone!",
    "1": "Bhukayo, you were a constant threat in attack, and that's no mean feat. You didn't quite get the goal you deserved, but those assists were worth their weight in gold. Keep shooting and they will go in!",
    "3": "Alinga, what a performance! Your goals were absolutely vital in this tight contest, and your finishing was clinical. You really stepped up when the team needed you, well done!",
    "8": "Nikhil, you were a rock in midfield. Your tackling and blocks were essential in disrupting the opposition's play, even though some passes didn't quite come off. Your defensive contribution was invaluable in securing the win.",
    "13": "Jamla, you put in a good effort in midfield, but your shot didn't quite hit the target this time. Your work rate was commendable though, helping out both in attack and defense. Keep working hard and the goals will come!",
    "7": "Jaltan, two goals and an assist \u2013 not bad at all! You were a real handful for their defense, and your creativity was excellent. Keep up the good work, champion!",
    "9": "Manesh, you were outstanding in goal! Your saves were crucial in keeping us in the game, and your presence in the box was commanding. You're a true shot-stopper!",
    "6": "Vinay, your two goals were hugely important in a tight game! You were a constant threat to their defense, and your determination was admirable. Well done on making such a big impact!",
    "10": "Prateek, you were solid in defense, and what a goal! Your tackles and blocks were vital in protecting our goal. A fantastic all-around performance from you, congratulations!",
    "16": "Kalyan, a hat-trick is a fantastic achievement! Your finishing was deadly, and you caused their defense all sorts of problems. You really stepped up when the team needed you, great job!",
    "4": "Rohan, fantastic performance today, with four goals! Your finishing was clinical, and you kept the pressure on their defense. You're a natural goalscorer!",
    "12": "Alishan, your saves were top-notch and helped the team secure the narrow victory! You commanded your area well and kept a cool head under pressure. Keep up the great work between the posts!",
    "17": "Tarun, you had a good game with those assists, even though the goals didn't come this time. Your passes created some excellent chances. Keep getting in those positions and the goals will follow soon!"
  },
  "match_description": "What a match! Street Legends have edged out Ballers for Life in a pulsating 10-9 victory. Alinga Halandh was simply unstoppable, bagging a whopping six goals for Street Legends, while Rohan Lavandeshki responded with four of his own for Ballers for Life in a valiant effort. The game saw a flurry of goals in the first half, but Ballers for Life fought back admirably, only for Kalyan Mbappi to seemingly put the game to bed, before Alinga Halandh sealed the deal for Street Legends in this goalfest. This is one for the ages!",
